const formatAmountInput=(value:any)=>{const raw=String(value??'').replace(/[,\s]/g,'');if(raw==='')return '';const negative=raw.startsWith('-'),unsigned=raw.replace(/-/g,''),hasDecimal=unsigned.includes('.'),parts=unsigned.split('.'),integer=(parts.shift()||'').replace(/\D/g,'').replace(/^0+(?=\d)/,'')||'0',fraction=parts.join('').replace(/\D/g,'');return `${negative?'-':''}${integer.replace(/\B(?=(\d{3})+(?!\d))/g,',')}${hasDecimal?'.'+fraction:''}`};const userError=(error:any,fallback='Something went wrong. Please try again.')=>{let message=String(error?.message||error||'').replace(/^Error invoking remote method '[^']+':\s*Error:\s*/,'').replace(/^Error:\s*/,'').trim();if(!message)return fallback;if(message==='A real date, description, and non-zero cent amount are required.')return 'Please enter a valid date, a description, and an amount other than zero.';if(message==='Only confirmed PT or affiliate business income/expenses can enter business profit.')return 'Business profit can include only confirmed Personal Training or Affiliate income or expenses. Turn off Include in business profit or adjust the type and scope.';if(message==='Income must be positive and expenses must use a minus amount.')return 'Please check the amount: income must be positive and expenses must use a minus amount.';if(message==='Transaction type, scope, category, or review state is invalid.')return 'Please complete the transaction type, scope, category, and review details before saving.';if(message.includes('Imported dates, descriptions, and amounts'))return 'This date, description, and amount come from the imported file. Undo the import before replacing source values.';if(message.includes('Matched transfers cannot be reclassified'))return 'This matched transfer is protected. Undo the related import before changing its classification.';if(message.includes('Transaction not found'))return 'This transaction is no longer available. Refresh the list and try again.';return message};const audToCents